*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  color: #333;
  background-color: #f9fafb;
}

/* Accessibility: Skip Link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: #2563eb;
  color: white;
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
  text-decoration: none;
}
.skip-link:focus {
  top: 0;
}

/* Typography & Layout */
header {
  background-color: #fff;
  padding: 2rem 1rem;
  text-align: center;
  border-bottom: 1px solid #e5e7eb;
}

h1 {
  margin: 0;
  font-size: 2.5rem;
  color: #111827;
}

main {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem 1rem;
}
main:focus {
  outline: none; /* No outline on main wrapper for mouse users */
}

.faq-container {
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 2rem;
}

h2 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
  color: #1f2937;
}

/* FAQ Widget Styles */
.example {
  border-bottom: 1px solid #e5e7eb;
}
.example:last-child {
  border-bottom: none;
}

.example h3 {
  margin: 0;
}

.faq-trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: #111827;
  text-align: left;
  cursor: pointer;
}

/* Focus styles for accessibility (Contrast >= 3.0) */
.faq-trigger:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 4px;
  border-radius: 4px;
}

.faq-trigger:hover {
  color: #2563eb;
}

.icon {
  transition: transform 0.2s ease;
  color: #6b7280;
}

/* Rotate icon when expanded */
.faq-trigger[aria-expanded="true"] .icon {
  transform: rotate(180deg);
}

.details {
  padding-bottom: 1.5rem;
  color: #4b5563;
}

.details[hidden] {
  display: none;
}

footer {
  text-align: center;
  padding: 2rem 1rem;
  color: #6b7280;
  font-size: 0.875rem;
}

/* Mobile responsive */
@media (max-width: 600px) {
  .faq-container {
    padding: 1.5rem 1rem;
  }
}
