  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: #111827;
  text-align: left;
  cursor: pointer;
}

/* Focus styles for accessibility (Contrast >= 3.0) */
.faq-trigger:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 4px;
  border-radius: 4px;
}

.faq-trigger:hover {
  color: #2563eb;
}

.icon {
  transition: transform 0.2s ease;
  color: #6b7280;
}

/* Rotate icon when expanded */
.faq-trigger[aria-expanded="true"] .icon {
  transform: rotate(180deg);
}

.details {
  padding-bottom: 1.5rem;
  color: #4b5563;
}

.details[hidden] {
  display: none;
}

footer {
  text-align: center;
  padding: 2rem 1rem;
  color: #6b7280;
  font-size: 0.875rem;
